from typing import Sequence

def idempotent_cgf(val: Sequence[float], w: Sequence[float], lam: float) -> float:
    """Idempotent CGF Lambda(lam) = max_x (lam*val(x) + w(x)). O(|X|) per call."""
    return max(lam * v + wx for v, wx in zip(val, w))

