function BICONJ(val, w, v, lam_lo, lam_hi, steps):
    best <- -infinity
    for k in 0 .. steps-1:
        lam <- lam_lo + (lam_hi - lam_lo) * k / (steps - 1)
        best <- max(best, lam * v - CGF(val, w, lam))
    return best
